// src/pages/Dashboard.js
import React, { useEffect, useState } from 'react';
import { Link } from 'react-router-dom';
import {
  LineChart, Line, XAxis, YAxis, Tooltip,
  ResponsiveContainer, CartesianGrid, Legend,
} from 'recharts';
import { getRuns, getSummary } from '../services';

export default function Dashboard() {
  const [summary, setSummary] = useState(null);
  const [runs,    setRuns]    = useState([]);

  useEffect(() => {
    getSummary().then(setSummary).catch(console.error);
    getRuns().then(setRuns).catch(console.error);
  }, []);

  const today = summary?.today || {};
  const trend = summary?.trend || [];

  return (
    <div className="page">
      <h1 className="page-title">Dashboard</h1>

      {/* Stats cards */}
      <div className="stats-grid">
        <div className="stat-card">
          <div className="stat-value">{today.total_runs ?? '—'}</div>
          <div className="stat-label">আজকের Runs</div>
        </div>
        <div className="stat-card green">
          <div className="stat-value">{today.total_passed ?? '—'}</div>
          <div className="stat-label">Passed</div>
        </div>
        <div className="stat-card red">
          <div className="stat-value">{today.total_failed ?? '—'}</div>
          <div className="stat-label">Failed</div>
        </div>
        <div className="stat-card blue">
          <div className="stat-value">
            {today.avg_pass_rate ? `${Math.round(today.avg_pass_rate)}%` : '—'}
          </div>
          <div className="stat-label">Pass Rate</div>
        </div>
      </div>

      {/* Pass rate trend chart */}
      <div className="card">
        <h2>Pass Rate Trend (শেষ ১৪ দিন)</h2>
        <ResponsiveContainer width="100%" height={220}>
          <LineChart data={trend}>
            <CartesianGrid strokeDasharray="3 3" stroke="#f0f0f0" />
            <XAxis dataKey="run_date" tick={{ fontSize: 12 }} />
            <YAxis domain={[0, 100]} tick={{ fontSize: 12 }} unit="%" />
            <Tooltip formatter={(v) => `${Math.round(v)}%`} />
            <Legend />
            <Line
              type="monotone" dataKey="pass_rate" name="Pass Rate"
              stroke="#4f46e5" strokeWidth={2} dot={{ r: 4 }}
            />
            <Line
              type="monotone" dataKey="failures" name="Failures"
              stroke="#ef4444" strokeWidth={2} dot={{ r: 4 }}
            />
          </LineChart>
        </ResponsiveContainer>
      </div>

      {/* Recent runs table */}
      <div className="card">
        <h2>Recent Runs</h2>
        <table className="table">
          <thead>
            <tr>
              <th>Run ID</th>
              <th>শুরু</th>
              <th>Status</th>
              <th>Passed</th>
              <th>Failed</th>
              <th>Pass Rate</th>
              <th>Duration</th>
            </tr>
          </thead>
          <tbody>
            {runs.map(run => {
              const passRate = run.total
                ? Math.round((run.passed / run.total) * 100)
                : 0;
              const duration = run.duration_ms
                ? `${(run.duration_ms / 1000).toFixed(1)}s`
                : '—';
              return (
                <tr key={run.id}>
                  <td>
                    <Link to={`/runs/${run.id}`} className="link">
                      {run.id.slice(0, 8)}…
                    </Link>
                  </td>
                  <td>{new Date(run.started_at).toLocaleString('bn-BD')}</td>
                  <td>
                    <span className={`badge ${run.status}`}>
                      {run.status === 'passed' ? '✅ Passed' : run.status === 'failed' ? '❌ Failed' : '⏳ Running'}
                    </span>
                  </td>
                  <td className="green-text">{run.passed}</td>
                  <td className="red-text">{run.failed}</td>
                  <td>{passRate}%</td>
                  <td>{duration}</td>
                </tr>
              );
            })}
            {runs.length === 0 && (
              <tr><td colSpan={7} style={{ textAlign: 'center', color: '#888' }}>কোনো run নেই</td></tr>
            )}
          </tbody>
        </table>
      </div>
    </div>
  );
}
